        clauses.append(clause)
    return variables, clauses

def quasi_monogenic_sequence(variables, clauses):
    n = len(variables)
    m = len(clauses)
    Q = [[0] * (n + 1) for _ in range(m + 1)]
    for i, clause in enumerate(clauses, start=1):
        for var in clause:
            Q[i][var - 1] = 1
    return Q

def run_trial(seed: int) -> dict:
